import{_ as t,H as a,f as o,i}from"./chunks/framework.BH2BK_3i.js";const m=JSON.parse('{"title":"结课测试｜快来检验下你的学习成果吧！","description":"","frontmatter":{},"headers":[],"relativePath":"TonyBai·Go语言第一课/结课测试｜快来检验下你的学习成果吧！.md","filePath":"TonyBai·Go语言第一课/结课测试｜快来检验下你的学习成果吧！.md","lastUpdated":1779817248000}'),r={name:"TonyBai·Go语言第一课/结课测试｜快来检验下你的学习成果吧！.md"};function n(_,e,s,l,p,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="结课测试-快来检验下你的学习成果吧" tabindex="-1">结课测试｜快来检验下你的学习成果吧！ <a class="header-anchor" href="#结课测试-快来检验下你的学习成果吧" aria-label="Permalink to &quot;结课测试｜快来检验下你的学习成果吧！&quot;">​</a></h1><p>你好，我是Tony Bai。</p><p>马上就是春节了，祝你新年快乐，万事顺意！到这里呢，我们专栏的正文就已经全部更新完毕了，只剩下最后的几篇加餐了，感谢你一直以来的支持和努力。</p><p>正因为如此，而且又恰逢春节假期，我决定把 <a href="http://time.geekbang.org/quiz/intro?act_id=1566&amp;exam_id=3856" target="_blank" rel="noreferrer">结课测试题</a> 的更新提前，你可以借着假期的时间，检验自己的学习成果，查缺补漏。剩下的加餐，我们依然会按正常的更新节奏进行更新。</p><p>而且，春节期间我们也准备了“春节特别放送”计划，除了今天的结课测试外，还有三篇重磅加餐：</p><ul><li>2月2日零点（初二），“大咖助阵”：分布式云存储工程师徐祥曦分享他与Go的二三趣事；</li><li>2月4日零点（初四）：“大咖助阵”：《Go语言高级编程》作者曹春晖“曹大”，带你分析Go语言的垃圾回收（GC）机制；</li><li>2月7日零点（初七）：Go Module 还没看过瘾？那这次，我会从Go Module的作者或维护者的角度，聊聊我们在规划、发布和维护Go Module时，需要考虑和注意什么。</li></ul><p>希望你在这个春节假期，玩得开心，学得愉快！如果你有什么不太清楚的地方，欢迎在留言区留言。</p><p><a href="http://time.geekbang.org/quiz/intro?act_id=1566&amp;exam_id=3856" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/TonyBai%C2%B7Go%E8%AF%AD%E8%A8%80%E7%AC%AC%E4%B8%80%E8%AF%BE/images/484138/28d1be62669b4f3cc01c36466bf811a4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/TonyBai%C2%B7Go%E8%AF%AD%E8%A8%80%E7%AC%AC%E4%B8%80%E8%AF%BE/images/484138/28d1be62669b4f3cc01c36466bf811a4.png" alt=""></a></a></p>',8)])])}const f=t(r,[["render",n]]);export{m as __pageData,f as default};
